CREATE TABLE voice_clue_candidates (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, voice_report_id TEXT NULL REFERENCES voice_reports(id) ON DELETE SET NULL, intercom_recording_id TEXT NULL REFERENCES intercom_recordings(id) ON DELETE SET NULL, submitted_by_user_id TEXT NOT NULL REFERENCES users(id), discoverer_user_id TEXT NULL REFERENCES users(id), source_type TEXT NOT NULL, ai_generated INTEGER NOT NULL DEFAULT 1 CHECK (ai_generated IN (0,1)), transcript_text TEXT NULL, candidate_json TEXT NOT NULL, asr_version TEXT NULL, model_version TEXT NULL, status TEXT NOT NULL CHECK (status IN ('queued','processing','pending_review','confirmed','rejected','failed')), retry_count INTEGER NOT NULL DEFAULT 0, failure_reason TEXT NULL, promoted_clue_id TEXT NULL REFERENCES clues(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
-- statement-break
CREATE INDEX idx_voice_clue_candidates_case_status ON voice_clue_candidates(case_id, status, created_at);
